import React, { useEffect, useMemo, useRef, useState } from "react";
import WatchlistRow from "./WatchlistRow";

const ROW_HEIGHT = 46;
const HEADER_HEIGHT = 38;

export default function Watchlist({
  symbols,
  selectedSymbol,
  getStockBySymbol,
  onSelectSymbol,
  onRemoveSymbol,
  onContextMenu,
  onReorderSymbol,
  flashMap,
}) {
  const listRef = useRef(null);
  const [scrollTop, setScrollTop] = useState(0);
  const [listHeight, setListHeight] = useState(360);
  const [draggedSymbol, setDraggedSymbol] = useState(null);

  useEffect(() => {
    function updateHeight() {
      if (!listRef.current) return;
      setListHeight(listRef.current.clientHeight);
    }

    updateHeight();
    window.addEventListener("resize", updateHeight);
    return () => window.removeEventListener("resize", updateHeight);
  }, []);

  const { visibleSymbols, offsetY, totalHeight } = useMemo(() => {
    const usableHeight = Math.max(listHeight - HEADER_HEIGHT, ROW_HEIGHT);
    const adjustedScrollTop = Math.max(scrollTop - HEADER_HEIGHT, 0);
    const startIndex = Math.max(
      Math.floor(adjustedScrollTop / ROW_HEIGHT) - 2,
      0
    );
    const visibleCount = Math.ceil(usableHeight / ROW_HEIGHT) + 6;
    const endIndex = Math.min(symbols.length, startIndex + visibleCount);

    return {
      visibleSymbols: symbols.slice(startIndex, endIndex),
      offsetY: startIndex * ROW_HEIGHT,
      totalHeight: symbols.length * ROW_HEIGHT,
    };
  }, [symbols, listHeight, scrollTop]);

  return (
    <div className="watchlist-table">
      <div
        className="watchlist-scroll"
        ref={listRef}
        onScroll={(event) => setScrollTop(event.currentTarget.scrollTop)}
      >
        <div className="table-row header watchlist-header-row">
          <span>Symbol</span>
          <span>Last</span>
          <span>Change</span>
          <span>Trend</span>
          <span></span>
        </div>

        <div className="watchlist-viewport" style={{ height: totalHeight }}>
          <div
            className="watchlist-window"
            style={{ transform: `translateY(${offsetY}px)` }}
          >
            {visibleSymbols.map((symbol) => (
              <WatchlistRow
                key={symbol}
                symbol={symbol}
                stock={getStockBySymbol(symbol)}
                isSelected={selectedSymbol === symbol}
                flashDirection={flashMap[symbol]}
                onClick={() => onSelectSymbol(symbol)}
                onRemove={() => onRemoveSymbol(symbol)}
                onContextMenu={(event) => onContextMenu(event, symbol)}
                onDragStart={() => setDraggedSymbol(symbol)}
                onDragOver={(event) => event.preventDefault()}
                onDrop={() =>
                  onReorderSymbol(
                    draggedSymbol,
                    draggedSymbol === symbol ? null : symbol
                  )
                }
              />
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}
